playground.code:
import random
random.seed(7)
secret = random.randint(1, 20)
for attempt in range(1, 4):
    guess = int(input('Guess: '))
    if guess < secret:
        print('too low')
    elif guess > secret:
        print('too high')
    else:
        print(f'got it in {attempt}')
        break
else:
    print(f'out of guesses; it was {secret}')
